import{c as a,Q as n,j as i,m as l}from"./chunks/framework.DOi4mjdC.js";const u=JSON.parse('{"title":"Matmul Tiling类使用说明","description":"","frontmatter":{},"headers":[{"level":1,"title":"Matmul Tiling类使用说明","slug":"matmul-tiling类使用说明"},{"level":2,"title":"需要包含的头文件","slug":"需要包含的头文件"}],"relativePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Tiling侧接口/Matmul-Tiling类/Matmul-Tiling类使用说明.md","filePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Tiling侧接口/Matmul-Tiling类/Matmul-Tiling类使用说明.md"}'),s={name:"api/SIMD-API/高阶API/矩阵计算/Matmul-Tiling侧接口/Matmul-Tiling类/Matmul-Tiling类使用说明.md"};function e(p,t,m,d,g,o){return n(),i("div",null,[...t[0]||(t[0]=[l(`<h1 id="matmul-tiling类使用说明" tabindex="-1">Matmul Tiling类使用说明 <a class="header-anchor" href="#matmul-tiling类使用说明" aria-label="Permalink to &quot;Matmul Tiling类使用说明&quot;">​</a></h1><p>Ascend C提供一组Matmul Tiling API，方便用户获取<a href="./../../Matmul-Kernel侧接口/Matmul使用说明.html#li5878185413338">Matmul kernel计算</a>时所需的Tiling参数。用户只需要传入A/B/C矩阵的Position位置、Format格式和DType数据类型等信息，调用API接口，即可获取到<a href="./../../Matmul-Kernel侧接口/Init-85.html">Init</a>中TCubeTiling结构体中的相关参数。</p><p>Matmul Tiling API分为Matmul单核Tiling接口、多核Tiling接口和BatchMatmul Tiling接口，分别用于Matmul单核计算、多核计算和BatchMatmul计算场景。获取Tiling参数的流程如下：</p><ol><li>创建一个单核Tiling对象，或多核Tiling对象，或BatchMatmul Tiling对象。</li><li>设置A、B、C、Bias的参数类型信息；M、N、Ka、Kb形状信息等。</li><li>调用<a href="./GetTiling.html">GetTiling</a>接口，获取Tiling信息。</li></ol><p>使用Matmul单核Tiling接口、多核Tiling接口和BatchMatmul Tiling接口获取Tiling参数的样例如下：</p><ul><li><p>Matmul单核Tiling</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>auto ascendcPlatform = platform_ascendc::PlatformAscendC(context-&gt;GetPlatformInfo());</span></span>
<span class="line"><span>matmul_tiling::MatmulApiTiling tiling(ascendcPlatform); </span></span>
<span class="line"><span>// 设置A、B、C、Bias矩阵Position、Format、DType信息</span></span>
<span class="line"><span>tiling.SetAType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16);</span></span>
<span class="line"><span>tiling.SetBType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16);   </span></span>
<span class="line"><span>tiling.SetCType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);   </span></span>
<span class="line"><span>tiling.SetBiasType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);   </span></span>
<span class="line"><span>tiling.SetShape(1024, 1024, 1024); // 设置单核计算的M、N、K大小</span></span>
<span class="line"><span>tiling.SetOrgShape(1024, 1024, 1024); // 设置原始输入M、N、K大小，单核Tiling与SetShape一致。若Ka,Kb不等长时，设置tiling.SetOrgShape(1024, 1024, 1024, 1280)   </span></span>
<span class="line"><span>tiling.EnableBias(true); // 设置matmul计算包含bias</span></span>
<span class="line"><span>tiling.SetBufferSpace(-1, -1, -1);  // 设定允许使用的空间，缺省使用该AI处理器所有空间</span></span>
<span class="line"><span>optiling::TCubeTiling tilingData;   </span></span>
<span class="line"><span>int64_t ret = tiling.GetTiling(tilingData);    // if ret = -1, get tiling failed</span></span></code></pre></div></li><li><p>Matmul多核Tiling</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>auto ascendcPlatform = platform_ascendc::PlatformAscendC(context-&gt;GetPlatformInfo());</span></span>
<span class="line"><span>matmul_tiling::MultiCoreMatmulTiling tiling(ascendcPlatform); </span></span>
<span class="line"><span>tiling.SetDim(1); // 设置参与计算的核数为1</span></span>
<span class="line"><span>tiling.SetAType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16);   </span></span>
<span class="line"><span>tiling.SetBType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16);   </span></span>
<span class="line"><span>tiling.SetCType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);   </span></span>
<span class="line"><span>tiling.SetBiasType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);   </span></span>
<span class="line"><span>tiling.SetShape(1024, 1024, 1024);   </span></span>
<span class="line"><span>tiling.SetSingleShape(1024, 1024, 1024);</span></span>
<span class="line"><span>tiling.SetOrgShape(1024, 1024, 1024); </span></span>
<span class="line"><span>tiling.EnableBias(true);   </span></span>
<span class="line"><span>tiling.SetBufferSpace(-1, -1, -1);  // 设定允许使用的空间，缺省使用该AI处理器所有空间</span></span>
<span class="line"><span>optiling::TCubeTiling tilingData;   </span></span>
<span class="line"><span>int64_t ret = tiling.GetTiling(tilingData);    // if ret = -1, get tiling failed</span></span></code></pre></div></li><li><p>BatchMatmul Tiling</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>auto ascendcPlatform = platform_ascendc::PlatformAscendC(context-&gt;GetPlatformInfo());</span></span>
<span class="line"><span>matmul_tiling::BatchMatmulTiling bmmTiling(ascendcPlatform); </span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>bmmTiling.SetAType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16);   </span></span>
<span class="line"><span>bmmTiling.SetBType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16);   </span></span>
<span class="line"><span>bmmTiling.SetCType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);   </span></span>
<span class="line"><span>bmmTiling.SetBiasType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);   </span></span>
<span class="line"><span>bmmTiling.EnableBias(true);</span></span>
<span class="line"><span>bmmTiling.SetShape(64, 48, 32);   </span></span>
<span class="line"><span>bmmTiling.SetSingleShape(64, 48, 32);</span></span>
<span class="line"><span>bmmTiling.SetOrgShape(64, 48, 32); </span></span>
<span class="line"><span>// Layout类型为NORMAL时,通过SetBatchInfoForNormal设置A、B、C矩阵的Layout轴信息</span></span>
<span class="line"><span>bmmTiling.SetBatchInfoForNormal(2, 2, 64, 48, 32);</span></span>
<span class="line"><span>// Layout类型为BSNGD、SBNGD、BNGS1S2时, 通过SetALayout、SetBLayout、SetCLayout设置A、B、C矩阵的Layout轴信息</span></span>
<span class="line"><span>// bmmTiling.SetALayout(3, 64, 2, 2, 32);</span></span>
<span class="line"><span>// bmmTiling.SetBLayout(3, 32, 2, 2, 48);</span></span>
<span class="line"><span>// bmmTiling.SetCLayout(3, 64, 2, 2, 48);</span></span>
<span class="line"><span>bmmTiling.SetBatchNum(2);</span></span>
<span class="line"><span>bmmTiling.SetBufferSpace(-1, -1, -1);  // 设定允许使用的空间，缺省使用该AI处理器所有空间</span></span>
<span class="line"><span>optiling::TCubeTiling tilingData;</span></span>
<span class="line"><span>int64_t ret = bmmTiling.GetTiling(tilingData);    // if ret = -1, get tiling failed</span></span></code></pre></div></li></ul><p>接口列表如下：</p><p><strong>表 1</strong> MatmulApiTiling/MultiCoreMatmulTiling/BatchMatmulTiling共有接口列表</p><table tabindex="0"><thead><tr><th>接口</th><th>功能</th></tr></thead><tbody><tr><td>SetAType</td><td>设置A矩阵的位置，数据格式，数据类型，是否转置等信息。</td></tr><tr><td>SetBType</td><td>设置B矩阵的位置，数据格式，数据类型，是否转置等信息。</td></tr><tr><td>SetCType</td><td>设置C矩阵的位置，数据格式，数据类型等信息。</td></tr><tr><td>SetDequantType</td><td>设置反量化的模式。</td></tr><tr><td>SetBiasType</td><td>设置Bias的位置，数据格式，数据类型等信息。</td></tr><tr><td>SetShape</td><td>设置Matmul单次计算的形状singleM、singleN、singleK，单位为元素个数。</td></tr><tr><td>SetOrgShape</td><td>设置Matmul计算时的原始完整的形状M、N、Ka、Kb，单位为元素个数。</td></tr><tr><td>SetALayout</td><td>设置A矩阵的Layout轴信息。</td></tr><tr><td>SetBLayout</td><td>设置B矩阵的Layout轴信息。</td></tr><tr><td>SetCLayout</td><td>设置C矩阵的Layout轴信息。</td></tr><tr><td>SetBatchInfoForNormal</td><td>设置A/B矩阵的M/N/K轴信息，以及A/B矩阵各自的Batch数。</td></tr><tr><td>SetBatchNum</td><td>设置多Batch计算的最大Batch数。</td></tr><tr><td>EnableBias</td><td>设置Bias是否参与运算。</td></tr><tr><td>SetBias</td><td>设置Bias是否参与运算。建议使用EnableBias接口。</td></tr><tr><td>SetFixSplit</td><td>设置固定的baseM、baseN、baseK，单位为元素个数。</td></tr><tr><td>SetBufferSpace</td><td>设置Matmul计算时可用的L1/L0C/UB空间大小，单位为字节。</td></tr><tr><td>SetTraverse</td><td>设置遍历方式，M轴优先还是N轴优先。</td></tr><tr><td>SetMadType</td><td>设置是否使能HF32模式。当前版本暂不支持。</td></tr><tr><td>SetSplitRange</td><td>设置baseM/baseN/baseK的最大值和最小值。</td></tr><tr><td>SetMatmulConfigParams</td><td>自定义设置MatmulConfig参数。</td></tr><tr><td>SetDoubleBuffer</td><td>设置A/B/C/Bias是否使能double buffer功能，以及是否需要做ND2NZ或者NZ2ND的转换。该接口为预留接口，当前版本暂不支持。</td></tr><tr><td>GetBaseM</td><td>获取baseM值。</td></tr><tr><td>GetBaseN</td><td>获取baseN值。</td></tr><tr><td>GetBaseK</td><td>获取baseK值。</td></tr><tr><td>GetTiling</td><td>获取Tiling参数。</td></tr></tbody></table><p><strong>表 2</strong> MultiCoreMatmulTiling其他接口</p><table tabindex="0"><thead><tr><th>接口</th><th>功能</th></tr></thead><tbody><tr><td>SetDim</td><td>设置多核Matmul时，可以参与运算的核数。</td></tr><tr><td>SetSingleRange</td><td>设置singleCoreM/singleCoreN/singleCoreK的最大值与最小值，单位为元素个数。</td></tr><tr><td>SetSingleShape</td><td>设置Matmul单核计算的形状singleCoreM、singleCoreN、singleCoreK，单位为元素个数。</td></tr><tr><td>GetSingleShape</td><td>获取计算后的singleCoreM/singleCoreN/singleCoreK。</td></tr><tr><td>SetAlignSplit</td><td>设置多核切分时singleCoreM/singleCoreN/singleCoreK的对齐值</td></tr><tr><td>GetCoreNum</td><td>获得多核切分后， 使用的numBlocks。</td></tr><tr><td>SetSplitK</td><td>多核场景，使能切K轴。建议使用EnableMultiCoreSplitK接口。</td></tr><tr><td>EnableMultiCoreSplitK</td><td>多核场景，使能切K轴。</td></tr></tbody></table><p><strong>表 3</strong> BatchMatmulTiling其他接口</p><table tabindex="0"><thead><tr><th>接口</th><th>功能</th></tr></thead><tbody><tr><td>GetCoreNum</td><td>获得多核切分后， 使用的numBlocks。</td></tr></tbody></table><h2 id="需要包含的头文件" tabindex="-1">需要包含的头文件 <a class="header-anchor" href="#需要包含的头文件" aria-label="Permalink to &quot;需要包含的头文件&quot;">​</a></h2><ul><li><p>Matmul单核Tiling</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;lib/matmul/matmul_tiling.h&quot;</span></span></code></pre></div></li><li><p>Matmul多核Tiling</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;lib/matmul/bmm_tiling.h&quot;</span></span></code></pre></div></li><li><p>BatchMatmul Tiling</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;lib/matmul/bmm_tiling.h&quot;</span></span></code></pre></div></li></ul>`,15)])])}const c=a(s,[["render",e]]);export{u as __pageData,c as default};
